"""Channel and seller partner workspace based on CRM campaign, activity, and commission records."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM channel and partner workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>کانال‌ها و شرکای فروش | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#17343c;background:#f4f7f3}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e0e9e5;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px;color:#16434a}.brand b{color:#108c86}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#587078;text-decoration:none;font-size:12px}.nav.active{background:#e6f3ef;color:#126a68}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.toolbar{display:flex;justify-content:space-between;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:16px}.filters{display:flex;gap:9px;flex-wrap:wrap}.field{display:grid;gap:6px;font-size:11px;color:#73868a}select,input{font:inherit;border:1px solid #dbe6e2;background:#fff;border-radius:9px;padding:10px;min-width:145px}h1{font-size:25px;margin:0 0 8px;color:#17343c}.sub{color:#6d8084;font-size:13px;line-height:1.8;margin:0 0 12px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.notice{background:#e9f4f0;border:1px solid #d5e8e0;border-right:3px solid #128b86;padding:11px 14px;border-radius:10px;color:#476b69;font-size:11px;line-height:1.8;margin:12px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e1eae6;border-radius:12px;padding:16px;box-shadow:0 4px 14px #17343c08;min-width:0}.label{color:#657b7e;font-size:11px}.value{font-size:22px;font-weight:bold;color:#17474a;margin:9px 0 3px}.meta{font-size:10px;color:#829395;line-height:1.7}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:14px}.heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:560px;font-size:11px}th,td{text-align:right;padding:9px 7px;border-bottom:1px solid #edf2ef}th{background:#f7faf8;color:#728482}td{color:#334e50}.list{display:grid;gap:8px}.item{border:1px solid #e7eeeb;border-radius:9px;padding:11px;font-size:11px;line-height:1.8}.item strong{display:block;color:#244f50}.pill{display:inline-block;border-radius:99px;background:#eef5f2;color:#50706c;padding:3px 8px;font-size:10px}.bars{display:grid;gap:11px}.barrow{display:grid;grid-template-columns:112px 1fr 70px;gap:8px;align-items:center;font-size:11px}.track{height:9px;background:#edf3ef;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#20aaa0,#15716f)}.empty,.foot{font-size:11px;line-height:1.8;color:#7b8998}.empty{text-align:center;padding:14px;border:1px dashed #d4e1dc;border-radius:9px}.links{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.link{border:1px solid #d8e5df;background:#fff;color:#276764;text-decoration:none;border-radius:8px;padding:9px 12px;font-size:11px}.foot{margin-top:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e0e9e5;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.toolbar{display:block}.filters{display:grid;grid-template-columns:1fr 1fr;margin-top:10px}.field,select,input{width:100%;min-width:0}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-channel-partners.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-marketing-planning">استراتژی و برنامه‌ریزی</a><a class="nav active" href="/workspace/crm-channel-partners" aria-current="page">کانال‌ها و شرکای فروش</a><a class="nav" href="/workspace/crm-sales">مدیریت فروش و درآمد</a><a class="nav" href="/workspace/crm-operations">عملیات فروش و بازاریابی</a><a class="nav" href="/workspace/crm-commissions">کمیسیون فروش</a></nav></aside><main class="main"><h1>کانال‌ها و شرکای فروش</h1><p class="sub">کارکرد کانال‌های دیجیتال، تلفنی، فروشگاهی و میدانی را با شواهد ثبت‌شده مقایسه کنید و برنامه‌های فروشندگان را ببینید.</p><div class="notice">مقایسهٔ کانال‌ها بر اساس داده‌های ثبت‌شدهٔ کمپین و تعامل مشتری است. پرونده‌های شرکا در همین واحد سازمانی نگهداری می‌شوند؛ ثبت و تغییر آن‌ها به مجوز مدیریت شریک نیاز دارد.</div><div class="toolbar"><div class="filters"><label class="field">فضای کاری<select id="workspace"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="unit"><option value="">در حال دریافت…</option></select></label><label class="field">از تاریخ<input id="start" type="date"></label><label class="field">تا تاریخ<input id="end" type="date"></label></div><button id="refresh" type="button">به‌روزرسانی</button></div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">کانال‌های کمپین</div><div id="channel-count" class="value">—</div><div class="meta">در بازهٔ انتخاب‌شده</div></article><article class="card"><div class="label">کمپین‌های سنجیده‌شده</div><div id="campaign-count" class="value">—</div><div class="meta">دارای دادهٔ ثبت‌شده</div></article><article class="card"><div class="label">تعداد تعاملات CRM</div><div id="activity-count" class="value">—</div><div class="meta">در ۳۰ روز گذشته</div></article><article class="card"><div class="label">برنامه‌های فعال فروشنده</div><div id="seller-count" class="value">—</div><div class="meta">طرح‌های کمیسیون فعال</div></article></section><div class="grid"><section class="card"><div class="heading"><h2>نتیجهٔ کمپین بر اساس کانال</h2><span class="meta">هزینه و درآمد تفکیک‌شده بر اساس ارز</span></div><div id="channel-performance" class="table-wrap"><div class="empty">در حال دریافت…</div></div><p class="foot">نرخ تبدیل بر پایهٔ دادهٔ قابل مشاهده نمایش داده می‌شود. مقادیر پولی با ارزهای متفاوت با هم جمع نمی‌شوند.</p></section><section class="card"><div class="heading"><h2>فعالیت ثبت‌شده بر اساس نوع کانال</h2></div><div id="activity-channels" class="bars"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>پروندهٔ شرکای کانال</h2><span class="meta">طرف‌های فروش، ارجاع و توزیع</span></div><div id="partner-registry" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>برنامه‌های کمیسیون فروشندگان</h2><span class="meta">شناسهٔ عضویت برای رعایت حداقل‌سازی داده</span></div><div id="seller-plans" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>داده‌های قابل استفاده و شکاف‌ها</h2></div><div id="coverage" class="list"><div class="empty">در حال دریافت…</div></div></section></div><div class="links"><a class="link" href="/workspace/crm-sales">مشاهدهٔ قیف فروش</a><a class="link" href="/workspace/crm-commissions">مدیریت برنامه‌های کمیسیون</a><a class="link" href="/workspace/crm-analytics">گزارش‌های تحلیلی</a></div><p class="foot">مقایسهٔ کانال‌ها توصیفی است و به‌تنهایی اثبات‌کنندهٔ اثر علّی یا برتری قطعی یک کانال نیست.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),unit=$("unit"),fmt=new Intl.NumberFormat("fa-IR",{maximumFractionDigits:2});
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function el(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(p){const r=await fetch(p,{credentials:"same-origin",headers:{Accept:"application/json","X-Workspace-ID":ws.value}});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"دریافت داده ناموفق بود");return d}
function money(map){return Object.entries(map||{}).map(([c,v])=>fmt.format(Number(v))+" "+c).join("، ")||"—"}
function channelTable(groups){const box=$("channel-performance"),table=document.createElement("table"),head=document.createElement("tr");["کانال","کمپین","نمایش","کلیک","سرنخ","تبدیل","نرخ تبدیل/کلیک","هزینهٔ ثبت‌شده","درآمد منتسب"].forEach(x=>head.append(el("th",x)));const th=document.createElement("thead");th.append(head);table.append(th);const body=document.createElement("tbody");if(!groups?.length){box.replaceChildren(el("div","برای این بازه دادهٔ کمپینی وجود ندارد.","empty"));return}for(const g of groups){const m=g.metrics,t=m.totals,row=document.createElement("tr");[g.key,m.campaign_count,t.impressions,t.clicks,t.leads,t.conversions,m.conversion_rate_per_click_percent==null?"—":fmt.format(m.conversion_rate_per_click_percent)+"٪",money(m.actual_spend_by_currency),money(m.attributed_revenue_by_currency)].forEach(x=>row.append(el("td",x)));body.append(row)}table.append(body);box.replaceChildren(table)}
function barChart(rows){const box=$("activity-channels");box.replaceChildren();if(!rows?.length){box.append(el("div","تعامل ثبت‌شده‌ای در این بازه نیست.","empty"));return}const max=Math.max(1,...rows.map(x=>x.current_count));for(const x of rows){const row=document.createElement("div");row.className="barrow";row.append(el("span",x.key));const tr=document.createElement("div");tr.className="track";const fill=document.createElement("div");fill.className="fill";fill.style.width=Math.max(2,100*x.current_count/max)+"%";tr.append(fill);row.append(tr,el("span",fmt.format(x.current_count)+" · قبل "+fmt.format(x.previous_count)));box.append(row)}}
function listItems(id,items,emptyText,render){const box=$(id);box.replaceChildren();if(!items?.length){box.append(el("div",emptyText,"empty"));return}for(const x of items)box.append(render(x))}
async function load(){if(!ws.value||!unit.value)return;say("در حال بارگذاری عملکرد کانال‌ها و فروشندگان…");const q=new URLSearchParams({period_start:$("start").value,period_end:$("end").value,organization_unit_id:unit.value,grouped_by:"channel",sort_by:"conversions",limit:"100"}),id=encodeURIComponent(unit.value);
const results=await Promise.allSettled([api("/api/v1/crm/analytics/campaign-performance/portfolio?"+q),api("/api/v1/crm/analytics/customer-activities/summary?window_days=30&organization_unit_id="+id),api("/api/v1/crm/commission-plans"),api("/api/v1/system/commission-organization-units"),api("/api/v1/crm/channel-partners?organization_unit_id="+id)]);const [p,a,s,scopes,partners]=results;
if(p.status==="fulfilled"){const d=p.value;$("channel-count").textContent=fmt.format(d.groups.length);$("campaign-count").textContent=fmt.format(d.totals.campaign_count);channelTable(d.groups)}else{channelTable([]);say("گزارش کمپین در دسترس نیست: "+p.reason.message,true)}
if(a.status==="fulfilled"){const d=a.value;$("activity-count").textContent=fmt.format(d.current_activity_count);barChart(d.by_channel)}else{barChart([])}
const permitted=scopes.status==="fulfilled"&&scopes.value.some(x=>x.id===unit.value);const plans=s.status==="fulfilled"?s.value.items.filter(x=>x.organization_unit_id===unit.value&&x.is_active):[];$("seller-count").textContent=fmt.format(plans.length);
listItems("seller-plans",plans,"برنامهٔ فعال کمیسیونی در این واحد ثبت نشده است.",x=>{const item=document.createElement("article");item.className="item";item.append(el("strong",x.name),el("span",fmt.format(Number(x.rate_percent))+"٪ · فعال","pill"));item.append(el("div",x.seller_membership_id?"شناسهٔ فروشنده: "+x.seller_membership_id:"برنامهٔ عمومی برای فروشندگان مجاز"));return item});
const partnerItems=partners.status==="fulfilled"?partners.value.items:[];
listItems("partner-registry",partnerItems,"برای این واحد هنوز شریکی ثبت نشده یا مجوز مشاهده ندارید.",x=>{const item=document.createElement("article");item.className="item";item.append(el("strong",x.name),el("span",x.partner_type+" · "+x.status,"pill"));item.append(el("div",[x.contact_name,x.territory].filter(Boolean).join(" · ")||"بدون اطلاعات تماس یا قلمرو"));return item});
const cover=[];cover.push(["شرکای کانال",partners.status==="fulfilled"?"داده دریافت شد":"نیازمند مجوز شریک"]);cover.push(["عملکرد کمپین",p.status==="fulfilled"?"داده دریافت شد":"نیازمند مجوز یا داده"]);cover.push(["تعاملات مشتری",a.status==="fulfilled"?"داده دریافت شد":"نیازمند مجوز پروفایل"]);cover.push(["برنامه‌های فروشنده",s.status==="fulfilled"?(permitted?"داده دریافت شد":"واحد خارج از دامنهٔ کمیسیون"):"نیازمند مجوز کمیسیون"]);listItems("coverage",cover,"",x=>{const item=document.createElement("article");item.className="item";item.append(el("strong",x[0]),el("span",x[1],"pill"));return item});
const failed=[p,a,s,partners].filter(x=>x.status==="rejected").length;if(!failed)say("گزارش کانال، شرکا و برنامه‌های فروشنده به‌روز شد.");}
async function init(){try{const w=await api("/api/v1/system/workspaces");ws.replaceChildren(...w.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!w.length)throw Error("فضای کاری یافت نشد");ws.value=w[0].id;const u=await api("/api/v1/system/organization-units");unit.replaceChildren(...u.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!u.length)throw Error("واحد سازمانی مجاز یافت نشد");unit.value=u[0].id;const now=new Date(),from=new Date(now);from.setDate(from.getDate()-29);$("start").value=from.toISOString().slice(0,10);$("end").value=now.toISOString().slice(0,10);await load()}catch(e){say("داده‌ها بارگیری نشد: "+e.message,true)}}
$("refresh").addEventListener("click",load);unit.addEventListener("change",load);ws.addEventListener("change",init);init();
})();"""
@router.get("/workspace/crm-channel-partners", response_class=HTMLResponse)
async def channel_partners_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-channel-partners.js")
async def channel_partners_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
